import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

// Reuse the dev certificate generated by `office-addin-dev-certs install`
// (in ~/.office-addin-dev-certs) so the browser/Office host trusts it after a
// one-time CA install. Fall back to Vite's automatic self-signed cert.
const certDir = path.join(os.homedir(), ".office-addin-dev-certs");
const certFile = path.join(certDir, "localhost.crt");
const keyFile = path.join(certDir, "localhost.key");
const https =
  fs.existsSync(certFile) && fs.existsSync(keyFile)
    ? { cert: fs.readFileSync(certFile), key: fs.readFileSync(keyFile) }
    : {};

export default defineConfig({
  plugins: [react()],
  css: {
    postcss: { plugins: [] },
  },
  server: {
    https,
    host: "127.0.0.1",
    port: 5173,
    strictPort: true,
  },
  build: {
    outDir: "dist",
    sourcemap: true,
  },
});
